{"type":"finding","source":"fs","path":"src/main.rs","start":42,"end":80,"rule_id":7,"rule":"aws-access-key","confidence_score":0}
```

Fields: type (always "finding" for findings), source ("fs"|"git"), path (string), start (u64, inclusive), end (u64, exclusive), rule_id (u32), rule (string), confidence_score (i8). Optional git fields: commit_id, change_kind.

### Implementation

```rust
use crate::core::NormalizedFinding;
use std::path::Path;

#[derive(Debug)]
pub struct ParseResult {
    pub findings: Vec<NormalizedFinding>,
    pub skipped_events: u64,
    pub malformed_lines: u64,
}

pub fn parse_findings_jsonl(jsonl: &str, corpus_root: &Path) -> ParseResult {
    let mut findings = Vec::new();
    let mut skipped = 0u64;
    let mut malformed = 0u64;

    for line in jsonl.lines() {
        if line.is_empty() { continue; }
        let v: serde_json::Value = match serde_json::from_str(line) {
            Ok(v) => v,
            Err(_) => { malformed += 1; continue; }
        };
        if v.get("type").and_then(|t| t.as_str()) != Some("finding") {
            skipped += 1;
            continue;
        }
        let raw_path = v["path"].as_str().unwrap_or("");
        let rel_path = crate::core::normalize_path(raw_path, corpus_root);
        findings.push(NormalizedFinding {
            path: rel_path,
            rule: v["rule"].as_str().unwrap_or("").to_string(),
            byte_start: v["start"].as_u64().unwrap_or(0),
            byte_end: v["end"].as_u64().unwrap_or(0),
            confidence: v["confidence_score"].as_i64().unwrap_or(0) as i8,
        });
    }
    findings.sort();
    findings.dedup();
    ParseResult { findings, skipped_events: skipped, malformed_lines: malformed }
}

pub fn parse_findings_file(path: &Path, corpus_root: &Path) -> std::io::Result<ParseResult> {
    let content = std::fs::read_to_string(path)?;
    Ok(parse_findings_jsonl(&content, corpus_root))
}
```

