use serde::{Deserialize, Serialize};
use std::path::Path;

/// A scanner finding normalized for evaluation.
///
/// All paths use forward slashes and are relative to the corpus root.
/// Byte offsets are inclusive-start, exclusive-end (matching the scanner's
/// wire format: `src/unified/events.rs:153-155`).
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
pub struct NormalizedFinding {
    pub path: String,
    pub byte_start: u64,
    pub byte_end: u64,
    pub rule: String,
    pub confidence: i8,
}

/// A single ground-truth annotation from a labeled corpus.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct TruthItem {
    pub path: String,
    pub line_start: u32,
    pub line_end: u32,
    pub label: TruthLabel,
    pub category: String,
}

/// Ground truth label from a labeled corpus.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum TruthLabel {
    Positive,
    Negative,
    Placeholder,
}

/// Classification of a single finding or truth item after matching.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum MatchClass {
    TruePositive,
    FalsePositive,
    FalseNegative,
    Unlabeled,
}

/// Normalize a raw path to a relative, forward-slash path from corpus root.
pub fn normalize_path(raw: &str, corpus_root: &Path) -> String {
    let p = Path::new(raw);
    let rel = if let Ok(r) = p.strip_prefix(corpus_root) {
        r.to_path_buf()
    } else {
        let canon_root = corpus_root.canonicalize().unwrap_or_else(|_| corpus_root.to_path_buf());
        let canon_p = p.canonicalize().unwrap_or_else(|_| p.to_path_buf());
        canon_p.strip_prefix(&canon_root).map(|r| r.to_path_buf()).unwrap_or_else(|_| p.to_path_buf())
    };
    let s = rel.to_string_lossy().replace('\\', "/");
    s.strip_prefix("./").unwrap_or(&s).to_string()
}
```

